#!/usr/bin/env python3
"""Pill by Pill v6.0a Patch: Manufacturers, CDMOs & Site Audit Comparator (Pipeline + UI Scaffold).

Creates and self-tests:
  - `pipeline/build_vendors.py` (FEI-keyed FDA Inspections, Form 483 themes, Warning Letters,
    DECRS operations, EMA EudraGMDP, and strictly isolated Drugs@FDA sponsor approval counts)
  - `site/js/vendors.js` (`#/ref/vendors` stage/modality/compliance filterable directory and
    `#/ref/vendors/compare/<fei1>/<fei2>[/<fei3>]` side-by-side site audit comparator)

Usage:
  python3 2026-11-20_v6.0a_vendors_cdmo_audit_comparator_patch.py --selftest
  python3 2026-11-20_v6.0a_vendors_cdmo_audit_comparator_patch.py --apply /path/to/unpacked_source
"""
import argparse
import json
import pathlib
import subprocess
import sys
import tempfile

BUILD_VENDORS_PY = '#!/usr/bin/env python3\n"""Build FEI-keyed Manufacturer & CDMO Site Audit Comparator datasets for Pill by Pill v6.0a.\n\nJoins public FDA Data Dashboard inspections (NAI/VAI/OAI), Form 483 citations (21 CFR themes),\nFDA Warning Letters, FDA DECRS registered facility capabilities, optional EMA EudraGMDP standing,\nand strictly separated Drugs@FDA sponsor approval counts into:\n  - site/data/vendors_index.json\n  - site/data/vendors/<fei>.json\n\nUsage:\n  python3 pipeline/build_vendors.py raw site/data\n"""\nimport collections\nimport json\nimport pathlib\nimport re\nimport sys\n\nCHECKED = "2026-11-20"\nCONFIDENTIAL_CDMO_NOTE = (\n    "Sponsor approval counts reflect Drugs@FDA application holders only. "\n    "Contract manufacturing (CDMO) client relationships in NDA/BLA Module 3 are confidential "\n    "under 21 CFR 314.430 unless publicly disclosed and are never inferred here."\n)\n\nOP_TO_MODALITY = [\n    (re.compile(r"\\bapi\\b|active pharmaceutical|bulk drug|synthesis", re.I), "small_molecule_api"),\n    (re.compile(r"tablet|capsule|oral solid|granul|compress", re.I), "oral_solid"),\n    (re.compile(r"sterile|inject|aseptic|lyophil|fill[- ]?finish|parenteral", re.I), "sterile_injectable"),\n    (re.compile(r"biolog|monoclonal|mab|recombinant|cell culture|ferment|vaccine", re.I), "biologics"),\n    (re.compile(r"peptide|oligonucleot|rna|sirna|antisense", re.I), "peptides_oligos"),\n    (re.compile(r"analy|testing|quality control|\\bqc\\b|microbiolog|stability", re.I), "analytical_qc"),\n]\n\nOP_TO_STAGE = [\n    (re.compile(r"preclinical|\\bglp\\b|toxicol|research|discovery", re.I), "preclinical"),\n    (re.compile(r"phase\\s*(1|i|2|ii)|clinical\\s*supply|investigational", re.I), "phase1_2"),\n    (re.compile(r"phase\\s*(3|iii)|\\bppq\\b|validation|scale[- ]?up", re.I), "phase3_ppq"),\n    (re.compile(r"manufacture|pack|label|sterile|api|commercial|analysis", re.I), "commercial"),\n]\n\nCFR_THEMES = [\n    (re.compile(r"211\\.113|211\\.42|aseptic|steril", re.I), "Aseptic & Sterility Controls"),\n    (re.compile(r"211\\.192|211\\.194|211\\.68|data integrity|record", re.I), "Production Records & Data Integrity"),\n    (re.compile(r"211\\.160|211\\.165|lab|testing|oot|oos", re.I), "Laboratory Controls & Testing"),\n    (re.compile(r"211\\.166|stabil", re.I), "Stability Program"),\n    (re.compile(r"211\\.67|clean|maint", re.I), "Equipment Cleaning & Maintenance"),\n    (re.compile(r"211\\.22|quality unit|capa", re.I), "Quality Unit & CAPA"),\n]\n\n\ndef _load_json(path: pathlib.Path, default):\n    return json.loads(path.read_text(encoding="utf-8")) if path.is_file() else default\n\n\ndef _norm_fei(val) -> str:\n    return re.sub(r"\\D+", "", str(val or "")).strip()\n\n\ndef _infer_tags(ops: list, rules: list) -> list:\n    joined = " ; ".join(str(x) for x in (ops or []))\n    out = []\n    for rx, tag in rules:\n        if rx.search(joined) and tag not in out:\n            out.append(tag)\n    return out\n\n\ndef _cfr_theme(cfr: str, desc: str) -> str:\n    blob = f"{cfr or \'\'} {desc or \'\'}"\n    for rx, label in CFR_THEMES:\n        if rx.search(blob):\n            return label\n    return "Other cGMP / 21 CFR"\n\n\ndef _region_of(country: str) -> str:\n    c = (country or "").strip().upper()\n    if c in ("US", "USA", "UNITED STATES", "UNITED STATES OF AMERICA"):\n        return "US"\n    if c in ("CA", "CANADA", "MX", "MEXICO", "PR", "PUERTO RICO"):\n        return "North America (non-US)"\n    if c in ("DE", "GERMANY", "FR", "FRANCE", "CH", "SWITZERLAND", "IT", "ITALY", "IE", "IRELAND",\n             "GB", "UK", "UNITED KINGDOM", "NL", "NETHERLANDS", "BE", "BELGIUM", "ES", "SPAIN", "SE", "SWEDEN", "DK", "DENMARK"):\n        return "Europe"\n    if c in ("IN", "INDIA", "CN", "CHINA", "JP", "JAPAN", "KR", "SOUTH KOREA", "SG", "SINGAPORE", "TW", "TAIWAN"):\n        return "Asia-Pacific"\n    return "Other / Global"\n\n\ndef _sponsor_counts(data_dir: pathlib.Path) -> dict:\n    """Count Drugs@FDA sponsor approvals strictly from existing drug files (never inferred for CDMOs)."""\n    counts = collections.Counter()\n    drugs_dir = data_dir / "drugs"\n    if not drugs_dir.is_dir():\n        return {}\n    for fp in drugs_dir.glob("*.json"):\n        d = json.loads(fp.read_text(encoding="utf-8"))\n        us = d.get("us") or {}\n        apps = us.get("applications") or []\n        seen_sponsors = set()\n        for row in apps:\n            if isinstance(row, list) and len(row) >= 3 and row[2]:\n                sp = str(row[2]).strip().upper()\n                if sp and sp not in seen_sponsors:\n                    seen_sponsors.add(sp)\n                    counts[sp] += 1\n    return dict(counts)\n\n\ndef build_vendors(raw_dir: pathlib.Path, data_dir: pathlib.Path) -> dict:\n    decrs = _load_json(raw_dir / "fda_decrs.json", [])\n    inspections = _load_json(raw_dir / "fda_inspections.json", [])\n    citations = _load_json(raw_dir / "fda_citations.json", [])\n    warnings = _load_json(raw_dir / "fda_warning_letters.json", [])\n    ema_gmp = _load_json(raw_dir / "ema_eudragmdp.json", {})\n    sponsor_map = _sponsor_counts(data_dir)\n\n    sites = {}\n\n    def ensure_site(fei: str, firm: str = "", city: str = "", state: str = "", country: str = ""):\n        if fei not in sites:\n            sites[fei] = {\n                "fei": fei,\n                "firm_name": firm.strip() or f"Facility {fei}",\n                "parent_company": firm.strip() or f"Facility {fei}",\n                "city": city.strip(),\n                "state": state.strip(),\n                "country": country.strip(),\n                "region": _region_of(country),\n                "operations": [],\n                "modalities": [],\n                "stages": [],\n                "inspections": [],\n                "counts": {"total": 0, "NAI": 0, "VAI": 0, "OAI": 0},\n                "latest_inspection": None,\n                "latest_classification": None,\n                "form_483_count": 0,\n                "top_483_themes": [],\n                "warning_letters": [],\n                "ema_gmp": None,\n                "sponsor_approvals": None,\n                "sources": [],\n                "checked": CHECKED,\n            }\n        else:\n            s = sites[fei]\n            if firm and s["firm_name"].startswith("Facility "):\n                s["firm_name"] = firm.strip()\n                s["parent_company"] = firm.strip()\n            if city and not s["city"]:\n                s["city"] = city.strip()\n            if country and not s["country"]:\n                s["country"] = country.strip()\n                s["region"] = _region_of(country)\n        return sites[fei]\n\n    # 1. DECRS facility registrations\n    for r in decrs:\n        fei = _norm_fei(r.get("fei"))\n        if not fei:\n            continue\n        s = ensure_site(fei, r.get("firm_name", ""), r.get("city", ""), r.get("state", ""), r.get("country", ""))\n        if r.get("parent_company"):\n            s["parent_company"] = r["parent_company"].strip()\n        ops = [str(o).strip() for o in (r.get("operations") or []) if str(o).strip()]\n        s["operations"] = sorted(set(s["operations"] + ops))\n        s["modalities"] = _infer_tags(s["operations"], OP_TO_MODALITY) or (r.get("modalities") or [])\n        s["stages"] = _infer_tags(s["operations"], OP_TO_STAGE) or (r.get("stages") or ["commercial"])\n        s["sources"].append({\n            "label": "FDA DECRS Drug Establishments Registration",\n            "url": r.get("url") or "https://www.accessdata.fda.gov/scripts/cder/drls/",\n        })\n\n    # 2. FDA Data Dashboard inspections\n    for ins in inspections:\n        fei = _norm_fei(ins.get("fei"))\n        if not fei:\n            continue\n        s = ensure_site(fei, ins.get("firm_name", ""), ins.get("city", ""), ins.get("state", ""), ins.get("country", ""))\n        cls = str(ins.get("classification") or "").strip().upper()\n        if cls not in ("NAI", "VAI", "OAI"):\n            cls = "OTHER"\n        rec = {\n            "date": str(ins.get("end_date") or ins.get("date") or ""),\n            "classification": cls,\n            "project_area": str(ins.get("project_area") or "Drugs"),\n            "inspection_id": str(ins.get("inspection_id") or ""),\n        }\n        s["inspections"].append(rec)\n        s["counts"]["total"] += 1\n        if cls in ("NAI", "VAI", "OAI"):\n            s["counts"][cls] += 1\n\n    # 3. Form 483 citations grouped by FEI\n    cites_by_fei = collections.defaultdict(list)\n    for c in citations:\n        fei = _norm_fei(c.get("fei"))\n        if fei:\n            cites_by_fei[fei].append(c)\n\n    # 4. Warning letters grouped by FEI\n    wl_by_fei = collections.defaultdict(list)\n    for w in warnings:\n        fei = _norm_fei(w.get("fei"))\n        if fei:\n            wl_by_fei[fei].append({\n                "date": str(w.get("date") or ""),\n                "subject": str(w.get("subject") or "CGMP / Drug Manufacturing"),\n                "status": str(w.get("status") or "Open"),\n                "url": str(w.get("url") or "https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/compliance-actions-and-activities/warning-letters"),\n            })\n\n    # 5. Finalize each site and write JSON files\n    vendors_dir = data_dir / "vendors"\n    vendors_dir.mkdir(parents=True, exist_ok=True)\n    index_rows = []\n\n    for fei, s in sorted(sites.items()):\n        s["inspections"].sort(key=lambda x: x["date"], reverse=True)\n        if s["inspections"]:\n            s["latest_inspection"] = s["inspections"][0]["date"]\n            s["latest_classification"] = s["inspections"][0]["classification"]\n            s["sources"].append({\n                "label": f"FDA Data Dashboard Inspections (FEI {fei})",\n                "url": f"https://datadashboard.fda.gov/ora/cd/inspections.htm",\n            })\n\n        # Form 483 themes\n        fcites = cites_by_fei.get(fei, [])\n        if fcites:\n            insp_ids = {str(c.get("inspection_id") or c.get("date") or i) for i, c in enumerate(fcites)}\n            s["form_483_count"] = len(insp_ids)\n            theme_counts = collections.Counter(_cfr_theme(c.get("cfr"), c.get("description")) for c in fcites)\n            s["top_483_themes"] = [{"theme": t, "count": n} for t, n in theme_counts.most_common(5)]\n\n        # Warning letters\n        s["warning_letters"] = sorted(wl_by_fei.get(fei, []), key=lambda x: x["date"], reverse=True)\n\n        # Optional EMA EudraGMDP\n        if fei in ema_gmp:\n            s["ema_gmp"] = ema_gmp[fei]\n            s["sources"].append({\n                "label": "EMA EudraGMDP",\n                "url": ema_gmp[fei].get("url") or "https://eudragmdp.ema.europa.eu/",\n            })\n\n        # Strictly separated Drugs@FDA sponsor approval count (exact firm match only)\n        sp_cnt = sponsor_map.get(s["firm_name"].upper(), 0)\n        s["sponsor_approvals"] = {\n            "drugs_count": sp_cnt,\n            "note": CONFIDENTIAL_CDMO_NOTE,\n        }\n\n        # Deduplicate sources\n        seen_u = set()\n        dedup = []\n        for src in s["sources"]:\n            u = src.get("url")\n            if u and u.startswith("https://") and u not in seen_u:\n                seen_u.add(u)\n                dedup.append(src)\n        s["sources"] = dedup\n\n        (vendors_dir / f"{fei}.json").write_text(json.dumps(s, ensure_ascii=False, indent=2), encoding="utf-8")\n        index_rows.append({\n            "fei": fei,\n            "firm_name": s["firm_name"],\n            "parent_company": s["parent_company"],\n            "city": s["city"],\n            "country": s["country"],\n            "region": s["region"],\n            "stages": s["stages"],\n            "modalities": s["modalities"],\n            "total_inspections": s["counts"]["total"],\n            "nai": s["counts"]["NAI"],\n            "vai": s["counts"]["VAI"],\n            "oai": s["counts"]["OAI"],\n            "latest_inspection": s["latest_inspection"],\n            "latest_classification": s["latest_classification"],\n            "form_483_count": s["form_483_count"],\n            "warning_letter_count": len(s["warning_letters"]),\n            "ema_status": (s["ema_gmp"] or {}).get("status") or "",\n        })\n\n    index_payload = {\n        "checked": CHECKED,\n        "count": len(index_rows),\n        "scope_note": CONFIDENTIAL_CDMO_NOTE,\n        "rows": index_rows,\n    }\n    (data_dir / "vendors_index.json").write_text(json.dumps(index_payload, ensure_ascii=False, indent=2), encoding="utf-8")\n    return {"sites_built": len(index_rows), "index_path": str(data_dir / "vendors_index.json")}\n\n\nif __name__ == "__main__":\n    if len(sys.argv) < 3:\n        sys.exit("Usage: python3 pipeline/build_vendors.py <raw_dir> <site/data>")\n    print(json.dumps(build_vendors(pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2])), indent=2))\n'
VENDORS_JS = '// Manufacturers, CDMOs & Site Audit Comparator (#/ref/vendors and #/ref/vendors/compare/<fei1>/<fei2>[/<fei3>])\n// Zero external dependencies; reads site/data/vendors_index.json and site/data/vendors/<fei>.json.\nimport { html } from "./ui.js";\nimport * as data from "./data.js";\nimport { page } from "./layout.js";\n\nexport const STAGES = [\n  ["preclinical", "Preclinical / GLP"],\n  ["phase1_2", "Phase I/II cGMP"],\n  ["phase3_ppq", "Phase III / PPQ"],\n  ["commercial", "Commercial Scale"],\n];\n\nexport const MODALITIES = [\n  ["small_molecule_api", "Small Molecule API"],\n  ["oral_solid", "Oral Solid Dosage"],\n  ["sterile_injectable", "Sterile Injectable / Fill-Finish"],\n  ["biologics", "Biologics / mAbs"],\n  ["peptides_oligos", "Peptides & Oligos"],\n  ["analytical_qc", "Analytical / QC Testing"],\n];\n\nconst HOME = ["Overview", "#/ref"];\n\nexport const vendorsIndex = () => data.getJSON("data/vendors_index.json");\nexport const vendorSite = (fei) => data.getJSON(`data/vendors/${encodeURIComponent(fei)}.json`);\n\nexport function filterVendors(rows, opts = {}) {\n  const q = (opts.q || "").trim().toLowerCase();\n  return rows.filter((r) => {\n    if (opts.stage && !(r.stages || []).includes(opts.stage)) return false;\n    if (opts.modality && !(r.modalities || []).includes(opts.modality)) return false;\n    if (opts.region && r.region !== opts.region) return false;\n    if (opts.compliance === "nai_latest" && r.latest_classification !== "NAI") return false;\n    if (opts.compliance === "has_oai" && !(r.oai > 0)) return false;\n    if (opts.compliance === "has_wl" && !(r.warning_letter_count > 0)) return false;\n    if (q) {\n      const hay = `${r.firm_name} ${r.parent_company} ${r.fei} ${r.city} ${r.country}`.toLowerCase();\n      if (!hay.includes(q)) return false;\n    }\n    return true;\n  });\n}\n\nexport async function vendorsPage(query) {\n  const idx = await vendorsIndex();\n  const stage = query.get("stage") || "";\n  const modality = query.get("modality") || "";\n  const region = query.get("region") || "";\n  const compliance = query.get("compliance") || "";\n  const q = query.get("q") || "";\n  const filtered = filterVendors(idx.rows || [], { stage, modality, region, compliance, q });\n\n  const regions = [...new Set((idx.rows || []).map((r) => r.region).filter(Boolean))].sort();\n  const body = html`\n    <section class="filters" aria-label="Filter manufacturers and sites">\n      <input id="v-q" type="search" value="${q}" placeholder="Search firm, FEI, city, or country…">\n      <select id="v-stage" aria-label="Development stage">\n        <option value="">All stages</option>\n        ${STAGES.map(([k, l]) => html`<option value="${k}"${stage === k ? " selected" : ""}>${l}</option>`)}\n      </select>\n      <select id="v-mod" aria-label="Modality">\n        <option value="">All modalities</option>\n        ${MODALITIES.map(([k, l]) => html`<option value="${k}"${modality === k ? " selected" : ""}>${l}</option>`)}\n      </select>\n      <select id="v-reg" aria-label="Region">\n        <option value="">All regions</option>\n        ${regions.map((r) => html`<option value="${r}"${region === r ? " selected" : ""}>${r}</option>`)}\n      </select>\n      <select id="v-comp" aria-label="Compliance status">\n        <option value="">Any compliance record</option>\n        <option value="nai_latest"${compliance === "nai_latest" ? " selected" : ""}>Latest inspection NAI</option>\n        <option value="has_oai"${compliance === "has_oai" ? " selected" : ""}>Has OAI on record</option>\n        <option value="has_wl"${compliance === "has_wl" ? " selected" : ""}>Has Warning Letter</option>\n      </select>\n    </section>\n    <p id="v-compare-bar" class="muted small">Select 2 or 3 sites below to compare their FDA/EMA audit records side by side. <button type="button" class="btn small" id="v-compare-go" disabled>Compare selected (0)</button></p>\n    <div class="tbl-wrap" tabindex="0" role="region" aria-label="Manufacturers and sites">\n      <table class="tbl"><thead><tr>\n        <th>Pick</th><th>Facility &amp; FEI</th><th>Location</th><th>Latest Audit</th><th>NAI / VAI / OAI</th><th>483s</th><th>Warning Letters</th>\n      </tr></thead>\n      <tbody>${filtered.map((r) => html`<tr>\n        <td><input type="checkbox" class="v-pick" value="${r.fei}" aria-label="Select ${r.firm_name} for comparison"></td>\n        <td><a href="#/ref/vendor/${r.fei}"><b>${r.firm_name}</b></a><br><span class="muted small">FEI ${r.fei}</span></td>\n        <td>${r.city ? `${r.city}, ` : ""}${r.country}</td>\n        <td>${r.latest_inspection || "—"} ${r.latest_classification ? html`<b>(${r.latest_classification})</b>` : ""}</td>\n        <td>${r.nai} / ${r.vai} / ${r.oai}</td>\n        <td>${r.form_483_count}</td>\n        <td>${r.warning_letter_count}</td>\n      </tr>`)}</tbody></table>\n    </div>\n    <p class="muted small">${idx.scope_note} Checked ${idx.checked}.</p>`;\n\n  return {\n    html: page({\n      trail: [HOME, ["Manufacturers & CDMOs"]],\n      title: "Manufacturers, CDMOs & Site Audits",\n      lede: `${filtered.length} of ${idx.count} registered facilities shown. Filter by development stage, modality, and FDA/EMA compliance standing.`,\n      body,\n    }),\n    mount(root) {\n      const go = () => {\n        const p = new URLSearchParams();\n        const vals = [["q", "#v-q"], ["stage", "#v-stage"], ["modality", "#v-mod"], ["region", "#v-reg"], ["compliance", "#v-comp"]];\n        for (const [k, sel] of vals) { const v = root.querySelector(sel)?.value.trim(); if (v) p.set(k, v); }\n        location.hash = "#/ref/vendors" + (p.toString() ? "?" + p.toString() : "");\n      };\n      ["#v-stage", "#v-mod", "#v-reg", "#v-comp"].forEach((s) => root.querySelector(s)?.addEventListener("change", go));\n      root.querySelector("#v-q")?.addEventListener("keydown", (e) => { if (e.key === "Enter") go(); });\n\n      const btn = root.querySelector("#v-compare-go");\n      const updateBar = () => {\n        const picked = [...root.querySelectorAll(".v-pick:checked")].map((x) => x.value).slice(0, 3);\n        btn.disabled = picked.length < 2;\n        btn.textContent = `Compare selected (${picked.length})`;\n      };\n      root.querySelectorAll(".v-pick").forEach((cb) => cb.addEventListener("change", updateBar));\n      btn?.addEventListener("click", () => {\n        const picked = [...root.querySelectorAll(".v-pick:checked")].map((x) => x.value).slice(0, 3);\n        if (picked.length >= 2) location.hash = `#/ref/vendors/compare/${picked.join("/")}`;\n      });\n    },\n  };\n}\n\nexport async function vendorComparePage(feis = []) {\n  const clean = feis.filter(Boolean).slice(0, 3);\n  if (clean.length < 2) {\n    return {\n      html: page({\n        trail: [HOME, ["Manufacturers & CDMOs", "#/ref/vendors"], ["Compare"]],\n        title: "Compare manufacturing sites",\n        lede: "Pick 2 or 3 sites from the Manufacturers & CDMOs directory to compare their inspection histories side by side.",\n        body: html`<p><a class="btn" href="#/ref/vendors">Browse facilities</a></p>`,\n      }),\n    };\n  }\n  const sites = await Promise.all(clean.map((f) => vendorSite(f)));\n  const row = (label, fn) => html`<tr><th scope="row">${label}</th>${sites.map((s) => html`<td>${fn(s)}</td>`)}</tr>`;\n  const body = html`\n    <p><a href="#/ref/vendors">← Back to Manufacturers &amp; CDMOs</a></p>\n    <div class="tbl-wrap" tabindex="0" role="region" aria-label="Side-by-side site audit comparison">\n      <table class="tbl cmp">\n        <thead><tr><th>Metric</th>${sites.map((s) => html`<th><a href="#/ref/vendor/${s.fei}">${s.firm_name}</a><br><span class="muted small">FEI ${s.fei}</span></th>`)}</tr></thead>\n        <tbody>\n          ${row("Location", (s) => `${s.city ? s.city + ", " : ""}${s.country}`)}\n          ${row("Registered capabilities (DECRS)", (s) => (s.operations || []).join(", ") || "Not listed")}\n          ${row("FDA Inspections (Total)", (s) => String(s.counts.total))}\n          ${row("NAI / VAI / OAI", (s) => `${s.counts.NAI} / ${s.counts.VAI} / ${s.counts.OAI}`)}\n          ${row("Latest FDA inspection", (s) => s.latest_inspection ? `${s.latest_inspection} (${s.latest_classification})` : "None on record")}\n          ${row("Form 483 inspections", (s) => String(s.form_483_count))}\n          ${row("Top Form 483 CFR themes", (s) => (s.top_483_themes || []).map((t) => `${t.theme} (${t.count})`).join("; ") || "None on record")}\n          ${row("FDA Warning Letters", (s) => s.warning_letters.length ? s.warning_letters.map((w) => `${w.date}: ${w.status}`).join("; ") : "None on record")}\n          ${row("EU GMP (EudraGMDP)", (s) => (s.ema_gmp && s.ema_gmp.status) || "Not matched")}\n          ${row("Drugs@FDA sponsor approvals*", (s) => String((s.sponsor_approvals && s.sponsor_approvals.drugs_count) || 0))}\n        </tbody>\n      </table>\n    </div>\n    <p class="muted small">*${sites[0].sponsor_approvals.note}</p>`;\n\n  return {\n    html: page({\n      trail: [HOME, ["Manufacturers & CDMOs", "#/ref/vendors"], ["Compare"]],\n      title: sites.map((s) => s.firm_name).join(" vs. "),\n      lede: "Side-by-side site compliance comparison from official FDA Data Dashboard, DECRS, Warning Letters, and EMA EudraGMDP records.",\n      body,\n    }),\n  };\n}\n'


def apply_patch(root: pathlib.Path) -> dict:
    pipe_dir = root / "pipeline"
    js_dir = root / "site" / "js"
    pipe_dir.mkdir(parents=True, exist_ok=True)
    js_dir.mkdir(parents=True, exist_ok=True)
    (pipe_dir / "build_vendors.py").write_text(BUILD_VENDORS_PY, encoding="utf-8")
    (js_dir / "vendors.js").write_text(VENDORS_JS, encoding="utf-8")
    return {
        "pipeline_written": "pipeline/build_vendors.py",
        "ui_written": "site/js/vendors.js",
        "routes_ready": ["#/ref/vendors", "#/ref/vendor/<fei>", "#/ref/vendors/compare/<fei1>/<fei2>"],
    }


def selftest() -> None:
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        raw_dir = root / "raw"
        data_dir = root / "site" / "data"
        raw_dir.mkdir(parents=True)
        (data_dir / "drugs").mkdir(parents=True)

        # Synthetic FEI fixtures (two realistic CDMO sites)
        (raw_dir / "fda_decrs.json").write_text(json.dumps([
            {
                "fei": "3002807001", "firm_name": "Alpha Biologics CDMO", "parent_company": "Alpha Group",
                "city": "Visp", "country": "Switzerland",
                "operations": ["Biologics Manufacture", "Sterile Injectable Fill-Finish", "Phase I/II Clinical Supply", "Analytical QC Testing"],
            },
            {
                "fei": "3004199002", "firm_name": "Beta Oral Solids Inc", "parent_company": "Beta Pharma",
                "city": "Greenville", "state": "NC", "country": "United States",
                "operations": ["Oral Solid Tablet Manufacture", "API Chemical Synthesis", "Commercial Packaging"],
            },
        ]), encoding="utf-8")

        (raw_dir / "fda_inspections.json").write_text(json.dumps([
            {"fei": "3002807001", "end_date": "2026-04-12", "classification": "NAI", "project_area": "Biologics", "inspection_id": "101"},
            {"fei": "3002807001", "end_date": "2024-09-03", "classification": "VAI", "project_area": "Biologics", "inspection_id": "102"},
            {"fei": "3004199002", "end_date": "2025-11-18", "classification": "OAI", "project_area": "Drugs", "inspection_id": "201"},
        ]), encoding="utf-8")

        (raw_dir / "fda_citations.json").write_text(json.dumps([
            {"fei": "3004199002", "inspection_id": "201", "cfr": "21 CFR 211.113(b)", "description": "Aseptic and microbiological control failures"},
            {"fei": "3004199002", "inspection_id": "201", "cfr": "21 CFR 211.192", "description": "Production record review and data integrity gaps"},
        ]), encoding="utf-8")

        (raw_dir / "fda_warning_letters.json").write_text(json.dumps([
            {"fei": "3004199002", "date": "2026-02-05", "subject": "CGMP / Finished Pharmaceuticals", "status": "Open"},
        ]), encoding="utf-8")

        (raw_dir / "ema_eudragmdp.json").write_text(json.dumps({
            "3002807001": {"status": "Valid EU GMP Certificate", "url": "https://eudragmdp.ema.europa.eu/"}
        }), encoding="utf-8")

        r = apply_patch(root)
        out = subprocess.run(
            [sys.executable, str(root / "pipeline" / "build_vendors.py"), str(raw_dir), str(data_dir)],
            capture_output=True, text=True, check=True,
        )
        res = json.loads(out.stdout)
        assert res["sites_built"] == 2, res

        idx = json.loads((data_dir / "vendors_index.json").read_text(encoding="utf-8"))
        assert idx["count"] == 2
        assert "21 CFR 314.430" in idx["scope_note"]

        s1 = json.loads((data_dir / "vendors" / "3002807001.json").read_text(encoding="utf-8"))
        s2 = json.loads((data_dir / "vendors" / "3004199002.json").read_text(encoding="utf-8"))
        assert s1["counts"]["NAI"] == 1 and s1["counts"]["VAI"] == 1 and s1["latest_classification"] == "NAI"
        assert "biologics" in s1["modalities"] and "sterile_injectable" in s1["modalities"] and "phase1_2" in s1["stages"]
        assert s2["counts"]["OAI"] == 1 and s2["form_483_count"] == 1 and len(s2["warning_letters"]) == 1
        assert any("Aseptic" in t["theme"] for t in s2["top_483_themes"])

        js_txt = (root / "site" / "js" / "vendors.js").read_text(encoding="utf-8")
        assert "export async function vendorsPage" in js_txt and "export async function vendorComparePage" in js_txt
        print("V60A_VENDORS_AUDIT_COMPARATOR_SELFTEST_PASSED", json.dumps(res, indent=2))


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Apply Pill by Pill v6.0a Vendors/CDMO Audit Comparator scaffold.")
    ap.add_argument("--apply", type=pathlib.Path, help="Path to unpacked source directory")
    ap.add_argument("--selftest", action="store_true", help="Run built-in verification tests")
    args = ap.parse_args(argv)
    if args.selftest:
        selftest()
        return 0
    if args.apply:
        print(json.dumps(apply_patch(args.apply), indent=2))
        return 0
    ap.error("Provide --apply <dir> or --selftest")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
